function nextProjectStateFromCounts(counts:Awaited<ReturnType<typeof productionModelCounts>>){if(counts.complete)return {pipeline:"QA_COMPLETE",nextAction:"GENERATE_PACKAGE"};if(Number(counts.production_slots_relink_required||0)>0)return {pipeline:"SLOT_ASSIGNMENT_WORKING",nextAction:"RELINK_PRODUCTION_SLOTS"};if(Number(counts.production_slots_pending||0)>0)return {pipeline:"SLOT_ASSIGNMENT_WORKING",nextAction:"ASSIGN_ASSETS_TO_SLOTS"};if(Number(counts.production_slots_assigned_for_qa||0)>0)return {pipeline:"QA_REVIEW_WORKING",nextAction:"FINALIZE_QA_OR_REJECT_SLOTS"};return {pipeline:"SLOT_ASSIGNMENT_WORKING",nextAction:"ASSIGN_ASSETS_TO_SLOTS"};}
