export async function reconcileLegacyProjectItemsFromProduction(env:Env,projectId:string){
  const project=await env.DB.prepare("SELECT active_version FROM automatic_projects WHERE id=?").bind(projectId).first<Record<string,unknown>>();
  if(!project)return {error:"PROJECT_NOT_FOUND",status:404,changed:0} as const;
  const version=Number(project.active_version||1),ts=nowMs();
  const [itemsResult,scenesResult,slotsResult]=await env.DB.batch<Record<string,unknown>>([
    env.DB.prepare("SELECT * FROM automatic_project_items WHERE project_id=? AND version=? ORDER BY created_at,id").bind(projectId,version),
    env.DB.prepare("SELECT id,scene_key FROM v2_production_scenes WHERE project_id=? AND version=?").bind(projectId,version),
    env.DB.prepare("SELECT id,scene_id,target_file,status,asset_id,candidate_id,qa_finalized_at,updated_at FROM v2_production_slots WHERE project_id=? AND version=?").bind(projectId,version),
  ]);
  const items=itemsResult.results||[],scenes=scenesResult.results||[],slots=slotsResult.results||[];
  if(!slots.length)return {project_id:projectId,version,changed:0,matched:0,reason:"NO_PRODUCTION_SLOTS"};
  const sceneIdByKey=new Map<string,string>();for(const row of scenes)sceneIdByKey.set(clean(row.scene_key),clean(row.id));
  const byScene=new Map<string,Record<string,unknown>[]>(),byTarget=new Map<string,Record<string,unknown>>(),byId=new Map<string,Record<string,unknown>>();
  for(const slot of slots){const sid=clean(slot.scene_id),target=clean(slot.target_file).toLowerCase(),slotId=clean(slot.id);if(sid){const arr=byScene.get(sid)||[];arr.push(slot);byScene.set(sid,arr);}if(target)byTarget.set(target,slot);if(slotId)byId.set(slotId,slot);}
  const statements:D1PreparedStatement[]=[];let matched=0,changed=0;const summary={FROZEN:0,ASSIGNED_FOR_QA:0,RELINK_REQUIRED:0,COLLECTING:0};
  for(const item of items){const itemKey=clean(item.item_key),target=clean(item.target_file).toLowerCase(),kind=upper(item.kind);let group:Record<string,unknown>[]=[];
    if(kind==="PRODUCTION_SLOT_RELINK"){const slot=byId.get(itemKey)||byTarget.get(target);if(slot)group=[slot];}
    if(!group.length&&itemKey){const sceneId=sceneIdByKey.get(itemKey);if(sceneId)group=byScene.get(sceneId)||[];}
    if(!group.length&&target){const slot=byTarget.get(target);if(slot)group=[slot];}
    if(!group.length)continue;matched++;
    const frozen=group.every(slot=>upper(slot.status)==="FROZEN"&&Boolean(clean(slot.asset_id)));
    const relink=group.some(slot=>upper(slot.status)==="RELINK_REQUIRED");
    const assigned=!relink&&group.some(slot=>upper(slot.status)==="ASSIGNED_FOR_QA"&&Boolean(clean(slot.asset_id)||clean(slot.candidate_id)));
    const state=frozen?"FROZEN":relink?"RELINK_REQUIRED":assigned?"ASSIGNED_FOR_QA":"COLLECTING";
    const stage=state==="FROZEN"?"DONE":state==="RELINK_REQUIRED"?"RELINK":state==="ASSIGNED_FOR_QA"?"QA":"DISCOVERY";
    const qaStatus=state==="FROZEN"?"QA_COMPLETE":state==="RELINK_REQUIRED"?"NEEDS_RELINK":state==="ASSIGNED_FOR_QA"?"QA_PENDING":null;
    const collectionStatus=state==="COLLECTING"?"COLLECTING":"COMPLETE";
    const direct=group.length===1?group[0]:null,linked=state==="FROZEN"&&direct?clean(direct.asset_id)||null:null;
    (summary as any)[state]++;
    const same=upper(item.status)===state&&upper(item.stage)===stage&&upper(item.collection_status)===collectionStatus&&upper(item.qa_status)===upper(qaStatus)&&clean(item.linked_asset_id)===clean(linked);
    if(same)continue;changed++;
    statements.push(env.DB.prepare(`UPDATE automatic_project_items SET status=?,stage=?,collection_status=?,qa_status=?,linked_asset_id=?,qa_ready_at=CASE WHEN ?='ASSIGNED_FOR_QA' THEN COALESCE(qa_ready_at,?) ELSE qa_ready_at END,qa_completed_at=CASE WHEN ?='FROZEN' THEN COALESCE(qa_completed_at,?) WHEN ?<>'FROZEN' THEN NULL ELSE qa_completed_at END,updated_at=? WHERE id=? AND project_id=?`).bind(state,stage,collectionStatus,qaStatus,linked,state,ts,state,ts,state,ts,item.id,projectId));
    if(["FROZEN","ASSIGNED_FOR_QA"].includes(state))statements.push(env.DB.prepare("UPDATE worker_work_items SET status='CANCELLED',last_action='PRODUCTION_SLOT_TRUTH_RECONCILED',updated_at=?,completed_at=COALESCE(completed_at,?) WHERE project_id=? AND item_id=? AND status IN ('READY','LEASED')").bind(ts,ts,projectId,item.id));
  }
  for(let offset=0;offset<statements.length;offset+=50)await env.DB.batch(statements.slice(offset,offset+50));
  if(changed)await env.DB.prepare("INSERT INTO automatic_project_events(id,project_id,event,status,detail,created_at) VALUES (?,?,?,?,?,?)").bind(id("PEV"),projectId,"LEGACY_PITEMS_RECONCILED_FROM_PSLOTS","OK",JSON.stringify({version,matched,changed,summary,source_of_truth:"PRODUCTION_SLOT"}),ts).run().catch(()=>undefined);
  return {project_id:projectId,version,matched,changed,summary,source_of_truth:"PRODUCTION_SLOT"};
}
export async function productionCompletionGate(env:Env,projectId:string){
  const counts=await productionModelCounts(env,projectId);
  const rows=await env.DB.prepare("SELECT id,type,status,file_name,created_at FROM v2_download_packages WHERE project_id=? AND type IN ('PROJECT_IMAGES_ZIP','PROJECT_SCRIPT_TXT','PROJECT_PUBLICATION_ZIP') ORDER BY created_at DESC LIMIT 30").bind(projectId).all<Record<string,unknown>>().catch(()=>({results:[]} as unknown as D1Result<Record<string,unknown>>));
  const latest=new Map<string,Record<string,unknown>>();for(const row of rows.results||[]){const type=upper(row.type);if(!latest.has(type))latest.set(type,row);}
  const ready=(type:string)=>["READY_FOR_DOWNLOAD","DOWNLOADED","COMPLETED"].includes(upper(latest.get(type)?.status));
  const artifacts={images:ready("PROJECT_IMAGES_ZIP"),script:ready("PROJECT_SCRIPT_TXT"),publication:ready("PROJECT_PUBLICATION_ZIP")};
  const packageReady=artifacts.images&&artifacts.script&&artifacts.publication;
  const deliveryReady=counts.production_slots_total>0&&counts.complete&&artifacts.images;
  return {...counts,images_ready:artifacts.images,delivery_ready:deliveryReady,package_ready:packageReady,final_artifacts_ready:artifacts,package_status:artifacts.images?"READY_FOR_DOWNLOAD":counts.complete?"PACKAGE_PENDING":"WAITING_QA",package_id:latest.get("PROJECT_IMAGES_ZIP")?.id||null,can_complete:counts.production_slots_total>0&&counts.complete&&packageReady};
}
